local TweenService     = game:GetService("TweenService")
local RunService       = game:GetService("RunService")
local Players          = game:GetService("Players")
local lp               = Players.LocalPlayer

local function tween(obj, info, props)
    return TweenService:Create(obj, info, props)
end
local function ti(t, s, d, r, rev, delay)
    s = s or Enum.EasingStyle.Quad
    d = d or Enum.EasingDirection.Out
    return TweenInfo.new(t, s, d, r or 0, rev or false, delay or 0)
end
local function lerp(a,b,t) return a+(b-a)*t end
local function hex(v) return Color3.fromRGB(math.floor(v/65536)%256, math.floor(v/256)%256, v%256) end

-- ── build root gui ──────────────────────────────────────────
local sg = Instance.new("ScreenGui")
sg.Name               = "SurfaceBoot"
sg.ResetOnSpawn       = false
sg.DisplayOrder       = 9999
sg.IgnoreGuiInset     = true
sg.ZIndexBehavior     = Enum.ZIndexBehavior.Sibling
pcall(function() sg.Parent = game:GetService("CoreGui") end)
if not sg.Parent then
    sg.Parent = lp:WaitForChild("PlayerGui")
end

