-- scanline animation (runs until gui destroyed)
local scanConn
scanConn = RunService.RenderStepped:Connect(function()
    if not sg.Parent then scanConn:Disconnect(); return end
    local t = tick() % 2 / 2
    scanFrame.Position = UDim2.new(0, 0, t, 0)
    scanFrame.BackgroundTransparency = 0.90 + 0.09*math.sin(tick()*3)
