gridFrame.BorderSizePixel   = 0
gridFrame.ZIndex            = 2

for gy = 1, 10 do
    for gx = 1, 20 do
        local dot = Instance.new("Frame", gridFrame)
        dot.Size = UDim2.new(0, 2, 0, 2)
        dot.Position = UDim2.new((gx-1)/20 + 0.025, 0, (gy-1)/10 + 0.05, 0)
