        Instance.new("UICorner", dot).CornerRadius = UDim.new(1,0)
    end
end

-- dot pulse animation
local dotConn
dotConn = RunService.RenderStepped:Connect(function()
    if not sg.Parent then dotConn:Disconnect(); return end
    local t = tick()
    for i, dot in ipairs(gridFrame:GetChildren()) do
        if dot:IsA("Frame") then
            local wave = math.sin(t*1.4 + i*0.31)*0.5+0.5
            dot.BackgroundTransparency = 0.70 + wave*0.28
        end
    end
end)

-- ── corner accent brackets ───────────────────────────────────
local function makeCorner(parent, px, py, rx, ry)
    local w, h = 36, 36
    local b = Instance.new("Frame", parent)
    b.Size = UDim2.new(0, w, 0, h)
    b.Position = UDim2.new(px, 0, py, 0)
    b.BackgroundTransparency = 1
    b.ZIndex = 10
    -- horizontal arm
    local hbar = Instance.new("Frame", b)
    hbar.Size = UDim2.new(1, 0, 0, 2)
    hbar.Position = UDim2.new(0,0, ry,0)
    hbar.BackgroundColor3 = C.accent
    hbar.BorderSizePixel = 0
    hbar.BackgroundTransparency = 0.3
    -- vertical arm
    local vbar = Instance.new("Frame", b)
    vbar.Size = UDim2.new(0, 2, 1, 0)
    vbar.Position = UDim2.new(rx, 0, 0, 0)
    vbar.BackgroundColor3 = C.accent
    vbar.BorderSizePixel = 0
    vbar.BackgroundTransparency = 0.3
    return b
end
