-- ANIMATION SEQUENCE
-- ═══════════════════════════════════════════════════════════

local function animIn()
    -- Stage 0: fade in backdrop (0 → 0.3s)
    tween(root, ti(0.35), {BackgroundTransparency=0}):Play()
    task.wait(0.3)

    -- Stage 1: dividers sweep out (0.3 → 0.65s)
    tween(divTop, ti(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size=UDim2.new(0,320,0,1)}):Play()
    tween(divBot, ti(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size=UDim2.new(0,320,0,1)}):Play()
    task.wait(0.2)

    -- Stage 2: ring fades in and starts spinning
    tween(ring,  ti(0.4), {ImageTransparency=0.5}):Play()
    tween(ring2, ti(0.4), {ImageTransparency=0.65}):Play()
    tween(diamond, ti(0.3), {BackgroundTransparency=0.1}):Play()
    task.wait(0.3)

    -- Stage 3: title reveal with stroke glow
    tween(titleLabel, ti(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
        {TextTransparency=0, Position=UDim2.new(0.5,-300, 0.5,-20)}):Play()
    tween(stroke, ti(0.5), {Transparency=0.3}):Play()
    task.wait(0.18)

    -- Stage 4: subtitle + version
    tween(subLabel, ti(0.4), {TextTransparency=0}):Play()
    task.wait(0.1)
    tween(verLabel, ti(0.4), {TextTransparency=0.2}):Play()
    task.wait(0.3)

    -- Stage 5: progress bar bg appears
    tween(barBg,  ti(0.3), {BackgroundTransparency=0.4}):Play()
    tween(stepLabel, ti(0.3), {TextTransparency=0}):Play()
    tween(pctLabel,  ti(0.3), {TextTransparency=0}):Play()
    task.wait(0.3)

    -- Stage 6: step-by-step loading
    local steps = {
        {label="resolving services",    pct=20},
        {label="hooking modules",       pct=45},
        {label="building interface",    pct=72},
        {label="finalizing payload",    pct=100},
    }

    for i, step in ipairs(steps) do
        stepLabel.Text = step.label .. " ..."
        -- text glitch effect: flicker 3 times
        for _ = 1, 2 do
            stepLabel.TextColor3 = C.accent
            task.wait(0.04)
            stepLabel.TextColor3 = C.dim
            task.wait(0.04)
        end
        stepLabel.TextColor3 = C.dim

        local frac = step.pct / 100
        local eStyle = i == 4 and Enum.EasingStyle.Back or Enum.EasingStyle.Quad
        tween(barFill, ti(0.38, eStyle, Enum.EasingDirection.Out),
            {Size=UDim2.new(frac, 0, 1, 0)}):Play()
        tween(barGlow, ti(0.38, eStyle, Enum.EasingDirection.Out),
            {Size=UDim2.new(frac, 0, 3, 0)}):Play()
        pctLabel.Text = step.pct .. "%"
        task.wait(0.42)
    end

    -- Stage 7: success — green flash
    stepLabel.Text = "ready"
    stepLabel.TextColor3 = C.green
    tween(barFill, ti(0.25), {BackgroundColor3=C.green}):Play()
    tween(barGlow, ti(0.25), {BackgroundColor3=C.green}):Play()
    tween(barGrad, ti(0.3), {Enabled=false}):Play()
    tween(stroke,  ti(0.25), {Color=C.green}):Play()
    tween(diamond, ti(0.25), {BackgroundColor3=C.green}):Play()
    tween(pctLabel, ti(0.2), {TextColor3=C.green}):Play()
    tween(bottomLine, ti(0.3), {TextTransparency=0.5}):Play()

    -- radiate a flash frame outward
    local flash = Instance.new("Frame", root)
    flash.Size = UDim2.new(1,0,1,0)
    flash.BackgroundColor3 = C.green
    flash.BackgroundTransparency = 0.92
    flash.BorderSizePixel = 0
    flash.ZIndex = 20
    tween(flash, ti(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        {BackgroundTransparency=1}):Play()

    task.wait(0.55)

    -- Stage 8: fade everything out
    local fadeInfo = ti(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
    for _, obj in ipairs({
        root, titleLabel, subLabel, verLabel,
        stepLabel, pctLabel, barBg, bottomLine,
        divTop, divBot,
    }) do
        if obj:IsA("TextLabel") or obj:IsA("TextBox") then
            tween(obj, fadeInfo, {TextTransparency=1}):Play()
        else
            tween(obj, fadeInfo, {BackgroundTransparency=1}):Play()
        end
    end
    tween(stroke,  fadeInfo, {Transparency=1}):Play()
    tween(ring,    fadeInfo, {ImageTransparency=1}):Play()
    tween(ring2,   fadeInfo, {ImageTransparency=1}):Play()
    tween(diamond, fadeInfo, {BackgroundTransparency=1}):Play()

    task.wait(0.6)
    sg:Destroy()
end

task.spawn(animIn)
task.wait(0.1)
-- END OF ANIMATION BLOCK


